    env = dict(os.environ, npm_config_cache=str(review / '.npm-cache'), npm_config_update_notifier='false')
    def run(args, **kwargs):
        return subprocess.run(args, cwd=review, env=env, **kwargs).returncode
    install = run(['npm', 'install', '--offline', '--ignore-scripts', '--no-audit', '--no-fund', str(root / 'vendor/hono-4.13.19.tgz')])
    if install:
        raise SystemExit(install)
    version = run(['node', '-p', \"require('./node_modules/hono/package.json').version\"])
    smoke = run(['npm', 'test'])
    checks = run(['node', '--input-type=module'], input=r'''import assert from 'node:assert/strict';
import app from './app.mjs';
const scenarios = [
  ['a7', 'day', 200, {id: 'a7', title: 'Harbor'}, 'dispatch,session,read'],
  ['a7', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['missing', 'day', 404, {error: 'not_found'}, 'dispatch,session,read'],
  ['b4', 'day', 502, {error: 'invalid_record'}, 'dispatch,session,read,error'],
  ['b4', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['missing', undefined, 401, {error: 'sign_in'}, 'dispatch,session'],
];
let failures = 0;
for (const [id, shift, status, body, steps] of scenarios) {
  const path = "'`/desk/${id}`;
  const request = new Request(`http://localhost${path}`, {
    method: '"'GET',
    headers: shift === undefined ? {} : {'x-shift': shift},
  });
  try {
    const response = await app.request(request);
    assert.ok(response instanceof Response);
    const actual = {
      status: response.status,
      steps: response.headers.get('x-desk-steps'),
      contentType: response.headers.get('content-type'),
      body: JSON.parse(await response.text()),
    };
    console.log(JSON.stringify({path, shift: shift ?? null, ...actual}));
    assert.deepEqual(actual, {status, steps, contentType: 'application/json', body});
  } catch (error) {
    failures++;
    console.error(error);
  }
}
process.exitCode = failures ? 1 : 0;''', text=True)
    raise SystemExit(version or smoke or checks)
