import { Hono } from 'hono';
const app = new Hono();
app.use('/desk/*', async (c, next) => {
  c.set('flow', ['dispatch']);
  await next();
  c.header('x-desk-steps', c.get('flow').join(','));
});
app.use('/desk/*', async (c, next) => {
  c.get('flow').push('session');
  if (c.req.header('x-shift') !== 'day') return c.json({error:'sign_in'}, 401);
  return next();
});
const roster = new Map([["a7", {"id": "a7", "title": "Harbor"}], ["b4", {"id": "b4", "title": 33}]]);
app.get('/desk/:id', c => {
  c.get('flow').push('read');
  const record = roster.get(c.req.param('id'));
  if (!record) return c.json({error:'not_found'},404);
  if (typeof record.title !== 'string' || !record.title.trim()) throw new TypeError('Invalid roster record');
  return c.json(record);
});
app.onError((err,c) => {c.get('flow').push('error'); return c.json({error:'invalid_record'},502);});
export default app;
import test from 'node:test';import assert from 'node:assert/strict';import app from './app.mjs';
test('valid title',async()=>{const r=await app.request('/desk/a7',{headers:{'x-shift':'day'}});assert.equal(r.status,200);assert.equal((await r.json()).title,'Harbor');});

